// StorageProvisioningServiceHandler is an implementation of the
// pilab.core.v1.StorageProvisioningService service.
type StorageProvisioningServiceHandler interface {
	// Physical Devices & Disks
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	RescanDevices(context.Context, *connect.Request[v1.RescanDevicesRequest]) (*connect.Response[v1.RescanDevicesResponse], error)
	InitializeDisk(context.Context, *connect.Request[v1.InitializeDiskRequest]) (*connect.Response[v1.InitializeDiskResponse], error)
	WipeDisk(context.Context, *connect.Request[v1.WipeDiskRequest]) (*connect.Response[v1.WipeDiskResponse], error)
	GetDiskHealth(context.Context, *connect.Request[v1.GetDiskHealthRequest]) (*connect.Response[v1.GetDiskHealthResponse], error)
	// Partitions & Filesystems
	CreatePartition(context.Context, *connect.Request[v1.CreatePartitionRequest]) (*connect.Response[v1.CreatePartitionResponse], error)
	DeletePartition(context.Context, *connect.Request[v1.DeletePartitionRequest]) (*connect.Response[v1.DeletePartitionResponse], error)
	FormatPartition(context.Context, *connect.Request[v1.FormatPartitionRequest]) (*connect.Response[v1.FormatPartitionResponse], error)
	ResizePartition(context.Context, *connect.Request[v1.ResizePartitionRequest]) (*connect.Response[v1.ResizePartitionResponse], error)
	MountFilesystem(context.Context, *connect.Request[v1.MountFilesystemRequest]) (*connect.Response[v1.MountFilesystemResponse], error)
	UnmountFilesystem(context.Context, *connect.Request[v1.UnmountFilesystemRequest]) (*connect.Response[v1.UnmountFilesystemResponse], error)
	// LVM
	ListLvm(context.Context, *connect.Request[v1.ListLvmRequest]) (*connect.Response[v1.ListLvmResponse], error)
	CreateLvmPv(context.Context, *connect.Request[v1.CreateLvmPvRequest]) (*connect.Response[v1.CreateLvmPvResponse], error)
	RemoveLvmPv(context.Context, *connect.Request[v1.RemoveLvmPvRequest]) (*connect.Response[v1.RemoveLvmPvResponse], error)
	CreateLvmVg(context.Context, *connect.Request[v1.CreateLvmVgRequest]) (*connect.Response[v1.CreateLvmVgResponse], error)
	RemoveLvmVg(context.Context, *connect.Request[v1.RemoveLvmVgRequest]) (*connect.Response[v1.RemoveLvmVgResponse], error)
	CreateLvmLv(context.Context, *connect.Request[v1.CreateLvmLvRequest]) (*connect.Response[v1.CreateLvmLvResponse], error)
	RemoveLvmLv(context.Context, *connect.Request[v1.RemoveLvmLvRequest]) (*connect.Response[v1.RemoveLvmLvResponse], error)
	CreateLvmThinPool(context.Context, *connect.Request[v1.CreateLvmThinPoolRequest]) (*connect.Response[v1.CreateLvmThinPoolResponse], error)
	// ZFS
	ListZfs(context.Context, *connect.Request[v1.ListZfsRequest]) (*connect.Response[v1.ListZfsResponse], error)
	CreateZpool(context.Context, *connect.Request[v1.CreateZpoolRequest]) (*connect.Response[v1.CreateZpoolResponse], error)
	DestroyZpool(context.Context, *connect.Request[v1.DestroyZpoolRequest]) (*connect.Response[v1.DestroyZpoolResponse], error)
	CreateZfsDataset(context.Context, *connect.Request[v1.CreateZfsDatasetRequest]) (*connect.Response[v1.CreateZfsDatasetResponse], error)
	DestroyZfsDataset(context.Context, *connect.Request[v1.DestroyZfsDatasetRequest]) (*connect.Response[v1.DestroyZfsDatasetResponse], error)
	CreateZfsZvol(context.Context, *connect.Request[v1.CreateZfsZvolRequest]) (*connect.Response[v1.CreateZfsZvolResponse], error)
	// Storage Pools (Declarative Ceph RBD, ZFS, LVM, NFS, Dir)
	ListStoragePools(context.Context, *connect.Request[v1.ListStoragePoolsRequest]) (*connect.Response[v1.ListStoragePoolsResponse], error)
	GetStoragePool(context.Context, *connect.Request[v1.GetStoragePoolRequest]) (*connect.Response[v1.GetStoragePoolResponse], error)
	CreateStoragePool(context.Context, *connect.Request[v1.CreateStoragePoolRequest]) (*connect.Response[v1.CreateStoragePoolResponse], error)
	UpdateStoragePool(context.Context, *connect.Request[v1.UpdateStoragePoolRequest]) (*connect.Response[v1.UpdateStoragePoolResponse], error)
	DeleteStoragePool(context.Context, *connect.Request[v1.DeleteStoragePoolRequest]) (*connect.Response[v1.DeleteStoragePoolResponse], error)
	// Volume Lifecycle on Storage Pools (Ceph RBD, ZFS, LVM, Directory)
	CreateVolume(context.Context, *connect.Request[v1.CreateVolumeRequest]) (*connect.Response[v1.CreateVolumeResponse], error)
	DeleteVolume(context.Context, *connect.Request[v1.DeleteVolumeRequest]) (*connect.Response[v1.DeleteVolumeResponse], error)
	ResizeVolume(context.Context, *connect.Request[v1.ResizeVolumeRequest]) (*connect.Response[v1.ResizeVolumeResponse], error)
	ListVolumes(context.Context, *connect.Request[v1.ListVolumesRequest]) (*connect.Response[v1.ListVolumesResponse], error)
	// Inheritable QoS & Live Throttling (QEMU iotune)
	SetDiskQoS(context.Context, *connect.Request[v1.SetDiskQoSRequest]) (*connect.Response[v1.SetDiskQoSResponse], error)
	GetDiskQoS(context.Context, *connect.Request[v1.GetDiskQoSRequest]) (*connect.Response[v1.GetDiskQoSResponse], error)
	// Software RAID (mdadm)
	ListRaidSets(context.Context, *connect.Request[v1.ListRaidSetsRequest]) (*connect.Response[v1.ListRaidSetsResponse], error)
	CreateRaidSet(context.Context, *connect.Request[v1.CreateRaidSetRequest]) (*connect.Response[v1.CreateRaidSetResponse], error)
	AssembleRaidSet(context.Context, *connect.Request[v1.AssembleRaidSetRequest]) (*connect.Response[v1.AssembleRaidSetResponse], error)
	GrowRaidSet(context.Context, *connect.Request[v1.GrowRaidSetRequest]) (*connect.Response[v1.GrowRaidSetResponse], error)
	FailRaidMember(context.Context, *connect.Request[v1.FailRaidMemberRequest]) (*connect.Response[v1.FailRaidMemberResponse], error)
	RemoveRaidMember(context.Context, *connect.Request[v1.RemoveRaidMemberRequest]) (*connect.Response[v1.RemoveRaidMemberResponse], error)
	ReplaceRaidMember(context.Context, *connect.Request[v1.ReplaceRaidMemberRequest]) (*connect.Response[v1.ReplaceRaidMemberResponse], error)
	DeleteRaidSet(context.Context, *connect.Request[v1.DeleteRaidSetRequest]) (*connect.Response[v1.DeleteRaidSetResponse], error)
	// Pool Performance Monitoring
	GetStorageIo(context.Context, *connect.Request[v1.GetStorageIoRequest]) (*connect.Response[v1.GetStorageIoResponse], error)
	// Maintenance and Tuning
	StartStorageMaintenance(context.Context, *connect.Request[v1.StartStorageMaintenanceRequest]) (*connect.Response[v1.StartStorageMaintenanceResponse], error)
	ListStorageMaintenanceTasks(context.Context, *connect.Request[v1.ListStorageMaintenanceTasksRequest]) (*connect.Response[v1.ListStorageMaintenanceTasksResponse], error)
	CancelStorageMaintenance(context.Context, *connect.Request[v1.CancelStorageMaintenanceRequest]) (*connect.Response[v1.CancelStorageMaintenanceResponse], error)
	GetStorageTuning(context.Context, *connect.Request[v1.GetStorageTuningRequest]) (*connect.Response[v1.GetStorageTuningResponse], error)
	SetStorageTuning(context.Context, *connect.Request[v1.SetStorageTuningRequest]) (*connect.Response[v1.SetStorageTuningResponse], error)
	// Snapshots and Backups
	ListStorageSnapshots(context.Context, *connect.Request[v1.ListStorageSnapshotsRequest]) (*connect.Response[v1.ListStorageSnapshotsResponse], error)
	CreateStorageSnapshot(context.Context, *connect.Request[v1.CreateStorageSnapshotRequest]) (*connect.Response[v1.CreateStorageSnapshotResponse], error)
	DeleteStorageSnapshot(context.Context, *connect.Request[v1.DeleteStorageSnapshotRequest]) (*connect.Response[v1.DeleteStorageSnapshotResponse], error)
	RestoreStorageSnapshot(context.Context, *connect.Request[v1.RestoreStorageSnapshotRequest]) (*connect.Response[v1.RestoreStorageSnapshotResponse], error)
	StartStorageBackup(context.Context, *connect.Request[v1.StartStorageBackupRequest]) (*connect.Response[v1.StartStorageBackupResponse], error)
	ListStorageBackups(context.Context, *connect.Request[v1.ListStorageBackupsRequest]) (*connect.Response[v1.ListStorageBackupsResponse], error)
	RestoreStorageBackup(context.Context, *connect.Request[v1.RestoreStorageBackupRequest]) (*connect.Response[v1.RestoreStorageBackupResponse], error)
	CancelStorageBackup(context.Context, *connect.Request[v1.CancelStorageBackupRequest]) (*connect.Response[v1.CancelStorageBackupResponse], error)
	ApplyRetention(context.Context, *connect.Request[v1.ApplyRetentionRequest]) (*connect.Response[v1.ApplyRetentionResponse], error)
	// Encryption and Key Management
	GetStorageEncryption(context.Context, *connect.Request[v1.GetStorageEncryptionRequest]) (*connect.Response[v1.GetStorageEncryptionResponse], error)
	EnableStorageEncryption(context.Context, *connect.Request[v1.EnableStorageEncryptionRequest]) (*connect.Response[v1.EnableStorageEncryptionResponse], error)
	DisableStorageEncryption(context.Context, *connect.Request[v1.DisableStorageEncryptionRequest]) (*connect.Response[v1.DisableStorageEncryptionResponse], error)
	LockStoragePool(context.Context, *connect.Request[v1.StorageKeyRequest]) (*connect.Response[v1.StorageKeyResponse], error)
	UnlockStoragePool(context.Context, *connect.Request[v1.StorageKeyRequest]) (*connect.Response[v1.StorageKeyResponse], error)
	RotateStorageKey(context.Context, *connect.Request[v1.StorageKeyRequest]) (*connect.Response[v1.StorageKeyResponse], error)
	BackupStorageKey(context.Context, *connect.Request[v1.BackupStorageKeyRequest]) (*connect.Response[v1.BackupStorageKeyResponse], error)
	VerifyStorageKey(context.Context, *connect.Request[v1.VerifyStorageKeyRequest]) (*connect.Response[v1.VerifyStorageKeyResponse], error)
	// Pool Access Control and Events
	ListStorageAccessRules(context.Context, *connect.Request[v1.ListStorageAccessRulesRequest]) (*connect.Response[v1.ListStorageAccessRulesResponse], error)
	SetStorageAccessRule(context.Context, *connect.Request[v1.SetStorageAccessRuleRequest]) (*connect.Response[v1.SetStorageAccessRuleResponse], error)
	DeleteStorageAccessRule(context.Context, *connect.Request[v1.DeleteStorageAccessRuleRequest]) (*connect.Response[v1.DeleteStorageAccessRuleResponse], error)
	ListStorageEvents(context.Context, *connect.Request[v1.ListStorageEventsRequest]) (*connect.Response[v1.ListStorageEventsResponse], error)
	AcknowledgeStorageEvents(context.Context, *connect.Request[v1.AcknowledgeStorageEventsRequest]) (*connect.Response[v1.AcknowledgeStorageEventsResponse], error)
	ClearStorageEvents(context.Context, *connect.Request[v1.ClearStorageEventsRequest]) (*connect.Response[v1.ClearStorageEventsResponse], error)
	// Migration Pre-Flight Classifier (Zero-Disk-Copy vs Block Copy)
	CheckMigrationStorage(context.Context, *connect.Request[v1.CheckMigrationStorageRequest]) (*connect.Response[v1.CheckMigrationStorageResponse], error)
}

